"""Identifier arithmetic and the (identifier, DATE) keying that a security master needs.

Two independent things live here, and the second is the one that costs money.

1. CHECK DIGITS. ISIN, CUSIP, SEDOL and FIGI each carry a self-check digit, and all four
   are pure arithmetic over the same base-36 alphabet. Running them costs nothing and
   catches the transcription errors that a string join cannot see. They are NOT proof the
   identifier exists - only that it was not mistyped.

2. WINDOWS. An identifier is not an entity, and neither one is stable. A ticker is
   recycled, a CIK outlives the company it was issued to, a name changes. So the key is
   `(identifier, date)`, never `identifier`, and a mapping used outside its window is a
   bug the same way a look-ahead is a bug: silent, plausible, and wrong in one direction.

Every number printed by the demo is computed here from the embedded fixtures. The live-SEC
figures quoted in SKILL.md were produced by these same functions pointed at the SEC's own
files, and `multi_ticker_rate()` / `name_windows()` take a supplied mapping so you can
reproduce them on today's copy rather than trusting a number in a document.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Iterable, Mapping, Sequence

import pandas as pd

# ------------------------------------------------------------------- the base-36 alphabet
ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
_VALUE = {c: i for i, c in enumerate(ALPHABET)}
#: CUSIP admits three extra characters for private placements (CUSIP Global Services)
_CUSIP_VALUE = dict(_VALUE, **{"*": 36, "@": 37, "#": 38})
#: SEDOL weights, applied to the six characters before the check digit
SEDOL_WEIGHTS = (1, 3, 1, 7, 3, 9)
#: SEDOL never uses a vowel, so a mistyped O/0 or I/1 is detectable by shape alone
SEDOL_VOWELS = frozenset("AEIOU")


def _digits_sum(value: int) -> int:
    """Sum the decimal digits of a doubled value: 12 -> 3. The Luhn fold."""
    return value // 10 + value % 10


def isin_check_digit(body: str) -> str:
    """Check digit for the 11 characters of an ISIN (2-letter country + 9-char NSIN).

    Letters expand to their two-digit base-36 value FIRST, then a Luhn pass runs over the
    resulting digit string from the right. Expanding after doubling is the classic wrong
    implementation and it agrees with the correct one often enough to look fine.
    """
    body = str(body).strip().upper()
    digits = "".join(str(_VALUE[c]) for c in body)
    total, double = 0, True
    for ch in reversed(digits):
        d = int(ch)
        if double:
            d = _digits_sum(d * 2)
        total += d
        double = not double
    return str((10 - total % 10) % 10)


def cusip_check_digit(body: str) -> str:
    """Check digit for the 8 characters of a CUSIP, doubling every second one from the LEFT."""
    body = str(body).strip().upper()
    total = 0
    for i, c in enumerate(body):
        v = _CUSIP_VALUE[c]
        total += _digits_sum(v * 2) if i % 2 else _digits_sum(v)
    return str((10 - total % 10) % 10)


def sedol_check_digit(body: str) -> str:
    """Check digit for the 6 characters of a SEDOL: a weighted modulus, not a Luhn."""
    body = str(body).strip().upper()
    total = sum(_VALUE[c] * w for c, w in zip(body, SEDOL_WEIGHTS))
    return str((10 - total % 10) % 10)


def figi_check_digit(body: str) -> str:
    """Check digit for the 11 characters of a FIGI - Luhn over base-36 values."""
    body = str(body).strip().upper()
    total = 0
    for i, c in enumerate(body):
        v = _VALUE[c]
        total += _digits_sum(v * 2) if i % 2 else _digits_sum(v)
    return str((10 - total % 10) % 10)


#: scheme -> (total length, check-digit function, extra structural test)
def _isin_shape(s: str) -> str:
    if not s[:2].isalpha():
        return "an ISIN starts with a 2-letter ISO country code"
    return ""


def _sedol_shape(s: str) -> str:
    if set(s[:6]) & SEDOL_VOWELS:
        return "a SEDOL never contains a vowel (AEIOU) - this is a transcription error"
    return ""


def _figi_shape(s: str) -> str:
    if s[2] != "G":
        return "a FIGI's third character is always 'G'"
    if set(s[:2]) & SEDOL_VOWELS:
        return "a FIGI's first two characters are consonants"
    return ""


SCHEMES: dict[str, tuple[int, object, object]] = {
    "isin": (12, isin_check_digit, _isin_shape),
    "cusip": (9, cusip_check_digit, lambda s: ""),
    "sedol": (7, sedol_check_digit, _sedol_shape),
    "figi": (12, figi_check_digit, _figi_shape),
}


@dataclass(frozen=True)
class CheckResult:
    """Why an identifier passed or failed. `ok` False always carries a reason.

    `ok` True means "not obviously mistyped", and nothing else. Three families of error
    survive it: an identifier that is well-formed and does not exist, one that exists and
    belongs to a different security than you think, and - because ISIN, CUSIP and FIGI
    are all Luhn-family - an adjacent 0<->9 transposition, which Luhn provably cannot
    detect. NXP's real ISIN NL0009538784 and the typo NL0090538784 both validate.
    """

    identifier: str
    scheme: str
    ok: bool
    reason: str = ""

    def __str__(self) -> str:
        return (f"{self.scheme:<5} {self.identifier:<14} "
                f"{'ok' if self.ok else 'FAIL: ' + self.reason}")


def check_identifier(identifier: str, scheme: str) -> CheckResult:
    """Validate one identifier's shape and check digit. Never raises on bad input."""
    scheme = str(scheme).lower()
    if scheme not in SCHEMES:
        return CheckResult(str(identifier), scheme, False,
                           f"unknown scheme; have {sorted(SCHEMES)}")
    s = str(identifier).strip().upper()
    n, fn, shape = SCHEMES[scheme]
    if len(s) != n:
        return CheckResult(s, scheme, False, f"length {len(s)}, expected {n}")
    allowed = _CUSIP_VALUE if scheme == "cusip" else _VALUE
    bad = [c for c in s if c not in allowed]
    if bad:
        return CheckResult(s, scheme, False, f"illegal character(s) {sorted(set(bad))}")
    why = shape(s)
    if why:
        return CheckResult(s, scheme, False, why)
    want = fn(s[:-1])
    if want != s[-1]:
        return CheckResult(s, scheme, False,
                           f"check digit is {s[-1]}, computed {want}")
    return CheckResult(s, scheme, True)


def cusip_from_isin(isin: str) -> str | None:
    """The CUSIP an ISIN embeds, or None when it does not embed one.

    Slicing `isin[2:11]` is the folklore version and it is right most of the time. The
    times it is wrong it returns a well-formed string rather than an error: NXP
    Semiconductors carries CUSIP N6596X109 (a CINS) against ISIN NL0009538784, and the
    slice is `000953878`, which is not NXP's identifier under any scheme. Validating the
    slice before returning it is the whole difference.
    """
    s = str(isin).strip().upper()
    if not check_identifier(s, "isin").ok:
        return None
    candidate = s[2:11]
    return candidate if check_identifier(candidate, "cusip").ok else None


def embedding_rate(pairs: Iterable[tuple[str, str]]) -> dict:
    """Share of (cusip, isin) pairs where `cusip_from_isin(isin) == cusip`.

    Feed it the `<cusip>`/`<isin>` pairs out of any N-PX or N-PORT filing. It is the
    measurement behind the rule "never derive one identifier from another": the rate is
    high enough to look safe in testing and never 100%.
    """
    ok = bad = 0
    misses = []
    for cusip, isin in pairs:
        if cusip_from_isin(isin) == str(cusip).strip().upper():
            ok += 1
        else:
            bad += 1
            misses.append((str(cusip), str(isin)))
    n = ok + bad
    return {"pairs": n, "embeds": ok, "does_not": bad,
            "pct": 100.0 * ok / n if n else float("nan"), "misses": misses}


# ---------------------------------------------------------------- (identifier, DATE) keys
@dataclass(frozen=True)
class Window:
    """One assignment of a name (or any label) to an identifier over HALF-OPEN [start, end).

    Half-open everywhere in this library, so two adjacent windows never both cover the
    changeover day. The SEC's `formerNames` uses inclusive `to` instead, which is why
    `name_windows()` adds a day when it converts.
    """

    identifier: str
    label: str
    start: pd.Timestamp
    end: pd.Timestamp | None            # None = still current

    def covers(self, ts) -> bool:
        t = pd.Timestamp(ts)
        return t >= self.start and (self.end is None or t < self.end)


def name_windows(former_names: Sequence[Mapping], current_name: str, *,
                 identifier: str = "") -> list[Window]:
    """SEC `formerNames` + the current name -> half-open windows, oldest first.

    Two conversions, both load-bearing:

      * the SEC's `to` is the LAST DAY a name was in effect, so `end = to + 1 day`. Read
        as an exclusive bound instead, a record with `from == to` (Apple has one) becomes
        a zero-width window that covers nothing and silently disappears.
      * the CURRENT name has no start date anywhere in the SEC's JSON, so its window opens
        where the newest former name closes. That is an inference, and it is the only one
        the primary source supports.
    """
    out = []
    for f in former_names:
        end = f.get("to")
        out.append(Window(identifier, str(f["name"]),
                          pd.Timestamp(str(f["from"])[:10]),
                          pd.Timestamp(str(end)[:10]) + pd.Timedelta(days=1) if end
                          else None))
    out.sort(key=lambda w: w.start)
    opens = max((w.end for w in out if w.end is not None), default=pd.Timestamp.min)
    out.append(Window(identifier, str(current_name), opens, None))
    return out


def window_gaps(windows: Sequence[Window]) -> pd.DataFrame:
    """Stretches covered by NO window - dates on which the identifier has no label.

    Apple's own SEC record has one: `APPLE COMPUTER INC` ends 2007-01-04 and `APPLE INC`
    opens 2007-01-10, so five days in the primary source name no registrant at all. A
    resolver that returns the nearest window instead of nothing has invented an answer.
    """
    ws = sorted((w for w in windows), key=lambda w: w.start)
    rows, reach, prev = [], None, ""
    for w in ws:
        if reach is not None and w.start > reach:
            rows.append({"identifier": w.identifier, "gap_from": reach,
                         "gap_to": w.start, "days": int((w.start - reach).days),
                         "before": prev, "after": w.label})
        if w.end is None:
            break
        if reach is None or w.end > reach:
            reach, prev = w.end, w.label
    return pd.DataFrame(rows)


def window_overlaps(windows: Sequence[Window]) -> pd.DataFrame:
    """Pairs of windows that both cover some date - i.e. where the mapping is a RELATION.

    The SEC's own file has these. Apple's CIK carries `APPLE COMPUTER INC/ FA` with
    from == to == 1997-07-28, nested inside the `APPLE COMPUTER INC` window, so
    "the registrant name of CIK 320193 on 1997-07-28" has two answers from the primary
    source. Code that assumes one silently takes whichever sorted first.
    """
    rows = []
    ws = sorted(windows, key=lambda w: (w.start, w.label))
    for i, a in enumerate(ws):
        for b in ws[i + 1:]:
            a_end = a.end if a.end is not None else pd.Timestamp.max
            b_end = b.end if b.end is not None else pd.Timestamp.max
            # strict, because the windows are half-open: two windows that merely touch at
            # a changeover date do not both cover any day
            if b.start < a_end and a.start < b_end:
                rows.append({"identifier": a.identifier, "a": a.label, "b": b.label,
                             "overlap_from": max(a.start, b.start),
                             "overlap_to": min(a_end, b_end)})
    return pd.DataFrame(rows)


def label_as_of(windows: Sequence[Window], as_of) -> list[str]:
    """Every label covering `as_of`. A list, because the answer is not always one."""
    return [w.label for w in windows if w.covers(as_of)]


def multi_ticker_rate(company_tickers: Iterable[Mapping]) -> dict:
    """The share of CIKs carrying more than one ticker, over a supplied mapping.

    Feed it `json.load(open('company_tickers.json')).values()` from
    https://www.sec.gov/files/company_tickers.json. The rate is quoted rather than
    hardcoded because the file changes daily and a stale number is worse than none.
    """
    by: dict[str, set] = {}
    for row in company_tickers:
        by.setdefault(str(row["cik_str"]).lstrip("0"), set()).add(str(row["ticker"]))
    if not by:
        return {"rows": 0, "ciks": 0, "multi": 0, "pct": float("nan"), "max_tickers": 0}
    multi = sum(1 for v in by.values() if len(v) > 1)
    return {"rows": sum(len(v) for v in by.values()), "ciks": len(by), "multi": multi,
            "pct": 100.0 * multi / len(by),
            "max_tickers": max(len(v) for v in by.values())}


